// ---- media ---------------------------------------------------------------

/// One file on disk the project references. Media is referenced, never
/// copied (spec §11); `bookmark` is the app's alias data for surviving a
/// move, base64 in the JSON.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Media {
    pub id: u32,
    pub path: String,
    #[serde(default)]
    pub bookmark: Option<String>,
    pub kind: MediaKind,
    #[serde(default)]
    pub duration: Ticks,
    #[serde(default)]
    pub width: u32,
    #[serde(default)]
    pub height: u32,
    #[serde(default)]
    pub fps: Fps,
    #[serde(default)]
    pub has_video: bool,
    #[serde(default)]
    pub has_audio: bool,
    #[serde(default)]
    pub has_alpha: bool,
    #[serde(default)]
    pub original: Option<MediaOriginal>,
    /// Camera log (format version 19, spec §11 GR-16): a video media's log
    /// curve and gamut, or the `lut` media converting it, at step 0. Written
    /// only when set, so a media with none writes the text it did.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub color: Option<MediaColor>,
    /// Speech spans, forward source ticks (format 29, spec §11 AU-110).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub speech: Option<Vec<[Ticks; 2]>>,
}

/// The file a playable copy was made from (format version 11, spec §11
/// #228-O): a WebM or Matroska file the app copied into a `.mov`. `path`
/// and `bookmark` above are the copy's; these are the original's, which is
/// what the app names, reveals and copies again when the copy is gone.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MediaOriginal {
    pub path: String,
----
    pub linked: Option<u32>,
}

/// What a clip shows. `media` is the only kind with a source bound —
/// `still`, `image`, `text`, `shape` and `nest` may have any duration.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Source {
    Media {
        media: u32,
        /// Source time of the clip's first frame.
        #[serde(rename = "in")]
        r#in: Ticks,
        /// Play the media back to front.
        ///
        /// The core does no pixel work, so this is a FACT about the clip,
        /// not an instruction: it changes neither the plan nor the recipe.
        /// Swift resolves it by substituting a pre-rendered reversed asset
        /// for this media's segments (spec §11 — "reverse is not native;
        /// M3 pre-renders reversed segments").
        ///
        /// `in` is then measured in that REVERSED stream, which has the
        /// same duration as the forward one — so an `in` of 0 is the
        /// media's last frame, and every time computation in this crate
        /// (trimming, splitting, `source_length`) stays correct with no
        /// case for it. That is the whole reason for the convention: the
        /// alternative, a forward-source in point, would make advancing
        /// `in` on a split run the wrong way.
        #[serde(default)]
        reversed: bool,
    },
    Still {
        media: u32,
        /// The source time the frozen frame is taken from.
        at: Ticks,
    },

    /// §5.2 `media[]` element MINUS `id` — the host probes the file and
    /// fills in kind, duration, size, rate and the track flags.
    ///
    /// **The new media's id is the project's `next_id` BEFORE this call.**
    /// There is one JSON op entry point (spec §11), so an op cannot return
    /// a value; reading `next_id` first is how the caller learns the id it
    /// is about to be able to `add_clip` with.
    ///
    /// Adding a file whose path is already in the list changes nothing (an
    /// identity): two entries for one path would each carry their own
    /// bookmark, thumbnails and peaks, and relinking one would leave the
    /// other missing. The caller that gets it looks the path up to find the
    /// id that is already there.
    ///
    /// `Err` for a descriptor that is not an object, an unknown or `id`
    /// key, a value that does not match the schema, an empty path, a
    /// negative duration, a media with pixels whose size or rate is not
    /// usable, or an `original` with an empty path. An `original` (spec §11
    /// #228-O) is stored with its path trimmed and a blank bookmark dropped.
    /// A `color` (spec §11 GR-16) is an `Err` in `set_media_color`'s
    /// sentences wherever that op would refuse it, `detected` aside.
    pub fn add_media(&self, descriptor: &Value) -> Result<Outcome, String> {
        let Value::Object(fields) = descriptor else {
            return Err(format!(
                "a media descriptor must be a json object, not {}",
                describe(descriptor)
            ));
        };
        if fields.contains_key("id") {
            return Err(format!(
                "a media descriptor must not carry an id: the project assigns it (this one gets {})",
                self.next_id
            ));
        }
        for key in fields.keys() {
            if !MEDIA_KEYS.contains(&key.as_str()) {
                return Err(format!("unknown key \"{key}\" in a media descriptor"));
            }
        }

        // Deserializing through `Media` itself means the descriptor's
        // schema is the model's schema — `kind` is checked against the
        // three variants, `fps` against `[num, den]` — with no second
        // spelling of it here. The id is stamped in first because `Media`
        // requires one.
        let mut with_id = descriptor.clone();
